mapper.select:
select sku, activity_id, quota_plan_id, stock_count, stock_count_surplus, product_amount
from raffle_quota_product
where sku = #{sku}

mapper.update:
update raffle_quota_product
set stock_count_surplus = stock_count_surplus - #{count}, update_time = now()
where sku = #{sku} and stock_count_surplus >= #{count}

update raffle_quota_product
set stock_count_surplus = 0, update_time = now()
where sku = #{sku}

update raffle_quota_product
set stock_count_surplus = #{remaining}, update_time = now()
where sku = #{sku} and stock_count_surplus > #{remaining}

mapper.select:
select sku, quota_plan_id, stock_count, stock_count_surplus, product_amount
from raffle_quota_product
where activity_id = #{activityId}
